WITH lines AS (SELECT id, created_at, item.qty FROM carts LATERAL VIEW OUTER EXPLODE(items) t AS item) SELECT CASE WHEN qty >= 4 THEN 'LARGE' ELSE 'SMALL' END AS qty_tier, PERCENTILE_APPROX(qty, ARRAY(0.25, 0.5, 0.75)) AS qty_quartiles, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min, COUNT(*) AS event_count FROM lines GROUP BY CASE WHEN qty >= 4 THEN 'LARGE' ELSE 'SMALL' END;
